package com.leapfrog.leapfrog.exception;

import org.springframework.http.HttpStatus;

public class LeapfrogException extends RuntimeException {
    private final HttpStatus status;

    public LeapfrogException(String message, HttpStatus status) {
        super(message);
        this.status = status;
    }

    public LeapfrogException(String message, Throwable cause, HttpStatus status) {
        super(message, cause);
        this.status = status;
    }

    public HttpStatus getStatus() {
        return status;
    }
}
